import sys
MOD=998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    arr = data[1:]

    factors = []
    primes = set()
    for a in arr:
        x = a
        f = {}
        d = 2
        while d * d <= x:
            if x % d == 0:
                e = 0
                while x % d == 0:
                    x //= d
                    e += 1
                f[d] = e
            d += 1
        if x > 1:
            f[x] = 1
        factors.append(f)
        primes.update(f)

    answer = 1
    for p in primes:
        total = sum(f.get(p, 0) for f in factors)
        powers = [1] * (total + 1)
        for i in range(1, total + 1):
            powers[i] = powers[i - 1] * p % MOD

        # dp[h] is the total weight of all prefixes whose current
        # normalized exponent is h. The weight includes all vertices so far.
        dp = {0: 1}
        crossing_powers = {}
        k = 1
        for f in factors:
            e = f.get(p, 0)
            nxt = {}
            if e == 0:
                for h, value in dp.items():
                    nxt[h] = (nxt.get(h, 0) + value * powers[h]) % MOD
            else:
                for h, value in dp.items():
                    for change in (-e, e):
                        nh = h + change
                        if nh >= 0:
                            weight = value * powers[nh] % MOD
                            nxt[nh] = (nxt.get(nh, 0) + weight) % MOD
                        else:
                            # The new point is a new minimum. All k prior
                            # exponents increase by -nh.
                            exponent = (-nh) * k
                            factor = crossing_powers.get(exponent)
                            if factor is None:
                                factor = pow(p, exponent, MOD)
                                crossing_powers[exponent] = factor
                            nxt[0] = (nxt.get(0, 0) + value * factor) % MOD
            dp = nxt
            k += 1

        answer = answer * sum(dp.values()) % MOD

    print(answer)

solve()

