import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    n,q=data[:2]; p=list(range(n)); sz=[1]*n; lo=list(range(n)); hi=list(range(n)); col=list(range(1,n+1)); cnt=[0]+[1]*n
    def find(x):
        while p[x]!=x:
            p[x]=p[p[x]]; x=p[x]
        return x
    def union(a,b):
        a=find(a); b=find(b)
        if a==b:return a
        if sz[a]<sz[b]: a,b=b,a
        p[b]=a; sz[a]+=sz[b]; lo[a]=min(lo[a],lo[b]); hi[a]=max(hi[a],hi[b])
        return a
    out=[]; j=2
    for _ in range(q):
        t=data[j]; j+=1
        if t==1:
            x,c=data[j]-1,data[j+1]; j+=2
            r=find(x); old=col[r]
            if old!=c:
                cnt[old]-=sz[r]; cnt[c]+=sz[r]; col[r]=c
            while lo[r]>0:
                a=find(lo[r]-1)
                if col[a]!=c: break
                r=union(r,a)
            while hi[r]<n-1:
                a=find(hi[r]+1)
                if col[a]!=c: break
                r=union(r,a)
        else:
            c=data[j]; j+=1; out.append(str(cnt[c]))
    sys.stdout.write('\n'.join(out))

