from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        starts = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            starts[b].append((a, i))

        heap = []
        gain = [0] * len(conflictingPairs)
        base = 0

        for r in range(1, n + 1):
            for a, i in starts[r]:
                heapq.heappush(heap, (-a, i))

            if not heap:
                base += r
                continue

            neg_a, i = heapq.heappop(heap)
            largest_a = -neg_a
            second_largest_a = -heap[0][0] if heap else 0
            heapq.heappush(heap, (neg_a, i))

            base += r - largest_a
            gain[i] += largest_a - second_largest_a

        return base + max(gain)

