import sys
from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[:2]
    values = data[2:]
    processes = [tuple(values[i:i + 4]) for i in range(0, len(values), 4)]

    def minimum_cost(target, process):
        if target == 0:
            return 0
        a, price_a, b, price_b = process
        g = gcd(a, b)
        step = b // g
        max_positive_x = (target - 1) // a

        # The option using only type S.
        best = ((target + a - 1) // a) * price_a

        # For each residue of x modulo b/g, the cost is linear as x
        # increases by b/g, so its minimum is at one of the endpoints.
        for residue in range(min(step, max_positive_x + 1)):
            max_k = (max_positive_x - residue) // step
            for k in {0, max_k}:
                x = residue + k * step
                y = (target - a * x + b - 1) // b
                cost = x * price_a + y * price_b
                if cost < best:
                    best = cost
        return best

    def feasible(target):
        total = 0
        for process in processes:
            total += minimum_cost(target, process)
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

