class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        size = min(n, x) + 1
        dp = [0] * size
        dp[0] = 1

        # dp[k] counts assignments to the processed performers using k stages,
        # including the score choices for those bands.
        for _ in range(n):
            ndp = [0] * size
            for k, ways in enumerate(dp):
                if ways == 0:
                    continue
                # Assign the new performer to one of the existing k stages.
                ndp[k] = (ndp[k] + ways * k) % MOD
                # Or use a previously empty stage and choose its score.
                if k + 1 < size:
                    ndp[k + 1] = (ndp[k + 1] + ways * (x - k) * y) % MOD
            dp = ndp
        return sum(dp) % MOD

