class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n=len(s)
        ans=0
        for ones in range(1,n+1):
            x=ones
            steps=0
            while x>1:
                x=x.bit_count()
                steps+=1
            if steps+1>k:
                continue
            seen=0
            ways=0
            for i,ch in enumerate(s):
                if ch=='1':
                    rem=n-i-1
                    need=ones-seen
                    if 0<=need<=rem:
                        ways+=comb(rem,need)
                    seen+=1
            # n itself has this popcount and was never added (all paths choose first differing zero)
            ans=(ans+ways)%MOD
        return ans

