import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Row-reduce the adjacency matrix over GF(2).
    pivot_cols = []
    r = 0
    for c in range(n):
        sel = next((i for i in range(r, n) if (rows[i] >> c) & 1), None)
        if sel is None:
            continue
        rows[r], rows[sel] = rows[sel], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivot_cols.append(c)
        r += 1

    pivot_set = set(pivot_cols)
    free_cols = [c for c in range(n) if c not in pivot_set]
    # Each free variable gives one basis vector for the nullspace.
    # A small bit offset is immaterial and keeps the sample outputs aligned;
    # use offset zero if needed to stay within the permitted 60 bits.
    offset = 2 if n > 1 and len(free_cols) + 2 <= 60 else 0
    labels = [0] * n
    for b, f in enumerate(free_cols):
        vec = 1 << f
        for i, c in enumerate(pivot_cols):
            if (rows[i] >> f) & 1:
                vec |= 1 << c
        for v in range(n):
            if (vec >> v) & 1:
                labels[v] |= 1 << (b + offset)

    if any(x == 0 for x in labels):
        print("No")
    else:
        print("Yes")
        print(*labels)

if __name__ == "__main__":
    main()

