from typing import List
from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        size = n * m
        dr = (1, 1, -1, -1)  # SE, SW, NW, NE; clockwise order
        dc = (1, -1, -1, 1)
        # dp[turned][direction][value][cell], where value is 0 or 2.
        turned = [[[array('H', [0]) * size for _ in range(2)] for _ in range(4)]][0]
        straight = [[[array('H', [0]) * size for _ in range(2)] for _ in range(4)]][0]
        # Process cells so the next cell in a direction has already been computed.
        for d in range(4):
            rows = range(n - 1, -1, -1) if dr[d] == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc[d] == 1 else range(m)
            for r in rows:
                for c in cols:
                    v = grid[r][c]
                    if v == 1:
                        continue
                    vi = 0 if v == 0 else 1
                    target_i = 1 - vi
                    nr, nc = r + dr[d], c + dc[d]
                    length = 1
                    if 0 <= nr < n and 0 <= nc < m:
                        ni = nr * m + nc
                        if grid[nr][nc] == (2 if v == 0 else 0):
                            length += turned[d][target_i][ni]
                    turned[d][vi][r * m + c] = length
        for d in range(4):
            rows = range(n - 1, -1, -1) if dr[d] == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc[d] == 1 else range(m)
            nd = (d + 1) % 4
            for r in rows:
                for c in cols:
                    v = grid[r][c]
                    if v == 1:
                        continue
                    vi = 0 if v == 0 else 1
                    target_i = 1 - vi
                    nr, nc = r + dr[d], c + dc[d]
                    best = 1
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == (2 if v == 0 else 0):
                        best = max(best, 1 + straight[d][target_i][nr * m + nc])
                    nr, nc = r + dr[nd], c + dc[nd]
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == (2 if v == 0 else 0):
                        best = max(best, 1 + turned[nd][target_i][nr * m + nc])
                    straight[d][vi][r * m + c] = best
        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    for d in range(4):
                        nr, nc = r + dr[d], c + dc[d]
                        length = 1
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                            length += straight[d][1][nr * m + nc]
                        ans = max(ans, length)
        return ans

