from typing import List
from functools import lru_cache
import sys
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        sys.setrecursionlimit(10000)
        n,m=len(grid),len(grid[0])
        dr=(1,1,-1,-1); dc=(1,-1,-1,1) # SE,SW,NW,NE clockwise
        @lru_cache(None)
        def dp(r,c,d,turned):
            v=grid[r][c]
            need=0 if v==2 else 2
            best=1
            nr,nc=r+dr[d],c+dc[d]
            if 0<=nr<n and 0<=nc<m and grid[nr][nc]==need:
                best=max(best,1+dp(nr,nc,d,turned))
            if not turned:
                nd=(d+1)%4
                nr,nc=r+dr[nd],c+dc[nd]
                if 0<=nr<n and 0<=nc<m and grid[nr][nc]==need:
                    best=max(best,1+dp(nr,nc,nd,1))
            return best
        ans=0
        for r in range(n):
            for c in range(m):
                if grid[r][c]==1:
                    for d in range(4):
                        ans=max(ans,dp(r,c,d,0))
        return ans

from typing import List
import math
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = list(range(1, n+1, 2))
        evens = list(range(2, n+1, 2))
        unused = set(range(1, n+1))
        ans=[]
        prev=None
        for pos in range(n):
            chosen=None
            for x in sorted(unused):
                p=x%2
                if prev is not None and p==prev:
                    continue
                rem=n-pos-1
                need_odd=need_even=0
                q=1-p
                for j in range(rem):
                    if (q if j%2==0 else p)==1:
                        need_odd+=1
                    else:
                        need_even+=1
                o=sum(1 for y in unused if y%2==1)- (p==1)
                e=sum(1 for y in unused if y%2==0)- (p==0)
                if o!=need_odd or e!=need_even:
                    ways=0
                else:
                    ways=math.factorial(o)*math.factorial(e)
                if k>ways:
                    k-=ways
                elif ways:
                    chosen=x
                    break
            if chosen is None:
                return []
            ans.append(chosen)
            unused.remove(chosen)
            prev=chosen%2
        return ans
